import{_ as n}from"./chunks/calibration-icon.BNE7NnUO.js";import{_ as i,C as s,o as l,c,a5 as r,E as e,j as o,a as d}from"./chunks/framework.DuVjalqf.js";const m="/rb_cobot_docs_muscat/images/move-menu/calibration-where.avif",g="/rb_cobot_docs_muscat/images/move-menu/calibration-panel.avif",p="/rb_cobot_docs_muscat/images/move-menu/calibration-tcp_pos-panel.avif",_="/rb_cobot_docs_muscat/images/move-menu/calibration-tcp_ori-panel.avif",u="/rb_cobot_docs_muscat/images/move-menu/calibration-user_3points-panel.avif",h="/rb_cobot_docs_muscat/images/move-menu/calibration-user_tcp-panel.avif",b="/rb_cobot_docs_muscat/images/move-menu/calibration-ext_axis-panel.avif",S=JSON.parse('{"title":"교정","description":"","frontmatter":{"title":"교정"},"headers":[],"relativePath":"manual/move-menu/calibration.md","filePath":"manual/move-menu/calibration.md","lastUpdated":1792552919000}'),P={name:"manual/move-menu/calibration.md"};function T(C,t,f,q,v,x){const a=s("DemoFrame");return l(),c("div",null,[t[0]||(t[0]=r('<h1 id="교정" tabindex="-1">교정 <a class="header-anchor" href="#교정" aria-label="Permalink to &quot;교정&quot;">​</a></h1><p><img src="'+n+'" alt="교정 아이콘"> TCP와 사용자 좌표계, 부가 축을 교정하는 메뉴입니다. 맨 위 목록에서 교정 종류를 고르면 아래 화면이 바뀝니다.</p><p>화면에서 파란 테두리로 표시한 곳입니다. 오른쪽 메뉴의 항목을 누르면 옆에 이 패널이 열립니다.</p><p><img src="'+m+'" alt="교정 위치"></p><h2 id="직접-해-보기" tabindex="-1">직접 해 보기 <a class="header-anchor" href="#직접-해-보기" aria-label="Permalink to &quot;직접 해 보기&quot;">​</a></h2><p>TCP 위치 교정을 두 가지 실습으로 해 볼 수 있습니다. 앞의 실습을 하지 않아도 시작할 수 있습니다. 목록은 이 화면 안에서만 유지되므로 실습을 시작할 때마다 비어 있는 상태에서 시작합니다.</p><h3 id="포인트가-부족할-때-경고-확인하기" tabindex="-1">포인트가 부족할 때 경고 확인하기 <a class="header-anchor" href="#포인트가-부족할-때-경고-확인하기" aria-label="Permalink to &quot;포인트가 부족할 때 경고 확인하기&quot;">​</a></h3><p>포인트를 하나만 추가하고 적용을 눌러 경고를 확인합니다.</p>',8)),e(a,{id:"move-menu-calibration-warning"}),t[1]||(t[1]=o("h3",{id:"포인트를-쌓아-계산-결과-확인하기",tabindex:"-1"},[d("포인트를 쌓아 계산 결과 확인하기 "),o("a",{class:"header-anchor",href:"#포인트를-쌓아-계산-결과-확인하기","aria-label":'Permalink to "포인트를 쌓아 계산 결과 확인하기"'},"​")],-1)),t[2]||(t[2]=o("p",null,"자세를 바꿔 가며 포인트를 4개 이상 쌓고 적용해 계산 결과를 확인합니다.",-1)),e(a,{id:"move-menu-calibration-result"}),t[3]||(t[3]=r('<h2 id="패널-화면" tabindex="-1">패널 화면 <a class="header-anchor" href="#패널-화면" aria-label="Permalink to &quot;패널 화면&quot;">​</a></h2><p><img src="'+g+'" alt="교정 패널"></p><p>위 화면은 가상 로봇(데모)에서 캡처한 것이라 값은 실제 로봇과 다를 수 있습니다.</p><p>모든 교정 버튼은 로봇이 움직이는 중이거나 연결되지 않은 상태(<code>DISCONNECT</code>)에서는 비활성화됩니다.</p><h2 id="교정-종류" tabindex="-1">교정 종류 <a class="header-anchor" href="#교정-종류" aria-label="Permalink to &quot;교정 종류&quot;">​</a></h2><h3 id="tcp-위치-교정" tabindex="-1">TCP 위치 교정 <a class="header-anchor" href="#tcp-위치-교정" aria-label="Permalink to &quot;TCP 위치 교정&quot;">​</a></h3><p><img src="'+p+'" alt="TCP 위치 교정"></p><ul><li><strong>추가</strong>: <strong>현재 관절 각도</strong>(J0~J6, 단위 °)를 포인트(P1, P2, …)로 목록에 더합니다. TCP 좌표가 아니라 관절 값이 저장되며, 목록에도 각도로 표시됩니다. 누를 때마다 그 순간 로봇의 자세가 한 줄씩 쌓이므로, 로봇을 움직여 자세를 바꾼 뒤 다시 누르세요.</li><li><strong>초기화</strong>: 목록을 비웁니다. 목록 한 줄의 <strong>X</strong>를 누르면 그 포인트만 지웁니다.</li><li><strong>적용</strong>: 목록의 관절 값을 모두 컨트롤러에 보내 TCP 위치를 계산하게 합니다. 목록이 비어 있으면 비활성화됩니다.</li><li>포인트가 없을 때는 &quot;포인트를 추가하세요.&quot;라고 표시됩니다.</li></ul><h4 id="포인트를-쌓는-방법" tabindex="-1">포인트를 쌓는 방법 <a class="header-anchor" href="#포인트를-쌓는-방법" aria-label="Permalink to &quot;포인트를 쌓는 방법&quot;">​</a></h4><ul><li><strong>다른 메뉴로 이동하면 목록이 사라집니다.</strong> 포인트 목록은 이 화면 안에서만 유지되어, 조그 같은 다른 메뉴를 눌렀다 돌아오면 비어 있습니다(가상 로봇에서 확인).</li><li>그래서 이 화면을 벗어나지 않고 로봇을 움직여야 합니다. 3D 화면 오른쪽의 손 모양 버튼(<strong>고스트 로봇</strong>)을 눌러 스위치를 켜면 3D 화면에 <strong>Control Panel</strong> 버튼이 나타나고, 이를 누르면 조그 패널이 이 화면 위에 열립니다. 가상 로봇에서는 이 패널의 + / − 버튼으로 자세를 바꾼 뒤 <strong>추가</strong>를 눌러 포인트를 쌓을 수 있었습니다.</li><li>실제 로봇에서 어떤 방식으로 자세를 바꾸는 것이 권장되는지(예: 직접 교시)는 확인하지 못했습니다.</li></ul><h4 id="적용을-누르면" tabindex="-1">적용을 누르면 <a class="header-anchor" href="#적용을-누르면" aria-label="Permalink to &quot;적용을 누르면&quot;">​</a></h4><p>컨트롤러 코드(<code>rb_service/calibration/calibration.cpp</code>의 <code>Auto_TCP_Position</code>)에서 확인한 동작입니다.</p><ul><li><strong>포인트는 4개 이상</strong> 필요합니다. 그보다 적으면 경고만 나오고 계산하지 않습니다.</li><li>계산은 각 포인트의 플랜지 위치와 자세에서, <strong>포인트마다 계산한 TCP 끝점이 서로 같은 곳에 모이는 TCP 오프셋(X·Y·Z)</strong> 을 구합니다. 그래서 TCP 끝을 같은 한 점에 둔 채 <strong>자세(회전)를 서로 다르게</strong> 바꿔 가며 포인트를 쌓아야 합니다. 자세가 거의 같은 포인트들만 있으면 계산에 쓸 수 있는 조합이 부족해 경고가 나옵니다.</li><li>오차가 큰 포인트 조합은 걸러 내며 다섯 번까지 반복해 값을 다듬습니다.</li><li>결과는 <strong>&quot;Auto TCP Result&quot;라는 메시지</strong>로 X, Y, Z와 오차(RMSE)가 나옵니다. 이 함수는 계산 결과를 알려 줄 뿐, <strong>TCP 툴 목록의 값을 바꾸는 코드는 들어 있지 않습니다.</strong> 계산 결과를 툴에 자동으로 넣어 주는지는 이 함수만으로는 알 수 없고, 다른 곳에서 반영하는 코드는 찾지 못했습니다. 결과를 툴에 쓰려면 결과 값을 확인한 뒤 툴 설정에서 입력하는 것으로 보이지만 확인하지는 못했습니다.</li><li>이 화면의 <strong>적용</strong> 버튼은 요청만 보내고 응답을 따로 처리하지 않습니다. 결과 메시지가 앱의 어느 곳에 어떻게 표시되는지는 확인하지 못했습니다.</li></ul><div class="info custom-block"><p class="custom-block-title">데모에서는</p><p>가상 로봇에서도 <strong>적용</strong>을 누르면 위 컨트롤러 코드를 같은 순서로 옮겨 계산하고, 결과(또는 경고) 메시지를 띄웁니다. 플랜지 좌표를 URDF 기준으로 가정하고 단위를 mm로 본 계산이라 실제 컨트롤러의 값과 같다고 보장할 수는 없습니다. 계산 결과는 메시지로만 나오며 TCP 툴 값은 바뀌지 않습니다.</p></div><h3 id="tcp-회전-교정" tabindex="-1">TCP 회전 교정 <a class="header-anchor" href="#tcp-회전-교정" aria-label="Permalink to &quot;TCP 회전 교정&quot;">​</a></h3><p><img src="'+_+'" alt="TCP 회전 교정"></p><p><strong>옵션</strong> 목록에서 <strong>전역 좌표계</strong>, <strong>로컬 좌표계</strong>, <strong>사용자 좌표계</strong> 중 하나를 고르고 <strong>적용</strong>을 누릅니다. 컨트롤러(<code>Auto_TCP_Orientation</code>)는 현재 관절 각도로 플랜지 자세를 구한 뒤, 고른 좌표계의 축에 TCP가 맞춰지도록 하는 RX·RY·RZ를 계산해 <strong>&quot;Auto TCP Orientation Result&quot; 메시지</strong>로 알려 줍니다. 위치 교정과 마찬가지로 이 함수에는 툴 값을 저장하는 코드가 없습니다.</p><h3 id="유저-좌표계-3개-지점을-이용한-교정" tabindex="-1">유저 좌표계: 3개 지점을 이용한 교정 <a class="header-anchor" href="#유저-좌표계-3개-지점을-이용한-교정" aria-label="Permalink to &quot;유저 좌표계: 3개 지점을 이용한 교정&quot;">​</a></h3><p><img src="'+u+'" alt="유저 좌표계 3개 지점 교정"></p><ol><li><strong>사용자 좌표계</strong>에서 교정할 User 0~7 중 하나를 고릅니다.</li><li><strong>포인트 순서</strong>를 고릅니다. 선택지는 <em>원점 → X축 → XY 평면</em>, <em>원점 → Y축 → YZ 평면</em>, <em>원점 → Z축 → ZX 평면</em>이며, 고른 순서에 맞는 그림이 아래에 표시됩니다.</li><li>포인트 1~3의 X·Y·Z(mm)를 직접 입력하거나, 각 포인트의 <strong>가져오기</strong>를 눌러 현재 TCP 위치 값을 채웁니다.</li><li><strong>저장</strong>을 누르면 입력값으로 교정을 요청합니다. 숫자가 아닌 값이 있으면 경고가 표시되고 요청하지 않습니다.</li></ol><h3 id="유저-좌표계-tcp-좌표계를-이용한-교정" tabindex="-1">유저 좌표계: TCP 좌표계를 이용한 교정 <a class="header-anchor" href="#유저-좌표계-tcp-좌표계를-이용한-교정" aria-label="Permalink to &quot;유저 좌표계: TCP 좌표계를 이용한 교정&quot;">​</a></h3><p><img src="'+h+'" alt="유저 좌표계 TCP 좌표계 교정"></p><p><strong>사용자 좌표계</strong>에서 User 0~7 중 하나를 고르고 <strong>저장</strong>을 누릅니다.</p><h3 id="부가-축" tabindex="-1">부가 축 <a class="header-anchor" href="#부가-축" aria-label="Permalink to &quot;부가 축&quot;">​</a></h3><p><img src="'+b+'" alt="부가 축 교정"></p><p><strong>조인트 번호</strong>에서 External Axis 0~6 중 하나를 고르고, 아래 버튼을 누릅니다. 버튼 이름은 UI에 영문으로 표시됩니다.</p><table tabindex="0"><thead><tr><th>버튼</th><th>설명</th></tr></thead><tbody><tr><td><strong>Calibration Start</strong></td><td>시작 명령(<code>clr</code>)을 보냅니다.</td></tr><tr><td><strong>Calibration Add+</strong></td><td>추가 명령(<code>add</code>)을 보냅니다.</td></tr><tr><td><strong>Calibration Finish</strong></td><td>종료 명령(<code>run</code>)을 보냅니다.</td></tr></tbody></table>',27))])}const D=i(P,[["render",T]]);export{S as __pageData,D as default};
